/* The PDF's text face, embedded, because the alternative is mojibake.
 *
 * jsPDF's built-in faces are the PDF standard 14 — Helvetica, Times, Courier —
 * and they are WinAnsiEncoding, which is Latin-1 and nothing else. Handed a
 * Cyrillic string, jsPDF does not fail and does not draw a blank: it writes the
 * low byte of each code point, so "Подготовка" comes out of the file as
 * ">43>B>2:0". Real characters, in the wrong alphabet, which is worse than an
 * obvious hole because it looks like content. Polish and Czech (Latin
 * Extended-A) break the same way; French and German survive only because they
 * happen to live inside Latin-1.
 *
 * **The face is Arimo**, and it is chosen for one property above its looks: it
 * is metrically compatible with Arial. Every advance width matches, so the
 * layout does not move — `textMetrics.ts` measures against the Helvetica/Arial
 * table, `PPTX_FONT_FACE` is Arial, and the deck's two renderings go on
 * agreeing about how wide a line is. A font with its own metrics would have
 * meant re-measuring the whole slide layout to fix an encoding bug.
 * SIL Open Font License 1.1, so it may be redistributed inside the bundle.
 *
 * **It is a subset**, at about a ninth of the original. The full faces are
 * 467KB and 474KB; what is here covers ASCII, Latin-1, Latin Extended-A (which
 * is Polish, Czech, Hungarian, Baltic, Turkish), Cyrillic including the
 * Ukrainian Ґ, and the typographic punctuation the deck draws — 440 glyphs,
 * 50KB per face, 135KB of base64 across the two. Greek, Hebrew, Vietnamese and
 * the rest of Arimo are left out; a plan written in those still exports, in the
 * shape of the missing-glyph box, which is the honest failure the standard
 * fonts would not give.
 *
 * Regenerated with, from the repository root:
 *
 *     npm i --no-save subset-font
 *     curl -sSLO https://raw.githubusercontent.com/googlefonts/arimo/main/fonts/ttf/Arimo-Regular.ttf
 *     curl -sSLO https://raw.githubusercontent.com/googlefonts/arimo/main/fonts/ttf/Arimo-Bold.ttf
 *     node scripts/buildPdfFont.mjs
 *
 * The character set that script keeps is written down in it, not here, so there
 * is one list rather than two.
 */

/** The family name the PDF asks for. Not "Arial": jsPDF resolves a name it
 * does not know to Helvetica and says nothing, so the name has to be one only
 * this file registers. */
export const PDF_TEXT_FONT_FAMILY = 'Arimo';

/** Filenames inside jsPDF's virtual file system. They are keys, not paths —
 * nothing is read from disk. */
export const PDF_TEXT_FONT_FILES = {
  normal: 'Arimo-Regular.ttf',
  bold: 'Arimo-Bold.ttf',
} as const;

